Translate("ruRU", "kingdom-of-stormwind", {
	title = "Королевство Штормград",
	sections = {
		{
			title = "Обзор",
			text = [=[Королевство Штормград — величайшая держава людей из тех, что еще стоят в {link:eastern-kingdoms}Восточных королевствах{/link}. Его сердце — белый город {link:stormwind-city}Штормград{/link}, а вокруг лежат чащи {link:elwynn-forest}Элвиннского леса{/link}, поля {link:westfall}Западного Края{/link}, холмы {link:redridge-mountains}Красногорья{/link} и сумрачные дебри {link:duskwood}Сумеречного леса{/link}. Дважды сокрушенное и дважды отстроенное, ныне оно ведет {link:alliance}Альянс{/link}. Но трон его пуст, войско далеко от дома, а границы полны врагов.]=],
		},
		{
			title = "Истоки",
			text = [=[Когда империя {link:arathor}Аратор{/link} начала распадаться, последние наследники крови {link:arathi-highlands}Арати{/link} покинули старую столицу, город {link:stromgarde-keep}Стром{/link}, и ушли на юг. В зеленой и укрытой от бурь земле они основали новое королевство и назвали его {link:azeroth}Азерот{/link}ом. Его столицей был {link:stormwind-city}Штормград{/link}. Королевство стало богатым и ни в ком не нуждалось и много веков держалось в стороне от раздоров северных держав. Вера в {link:holy-light}Свет{/link} пустила там глубокие корни, и служители Света в {link:northshire-abbey}Североземье{/link} хранили ее древнейшие книги.]=],
		},
		{
			title = "История",
			text = [=[• {b}Первая война.{/b} Орочья {link:horde}Орда{/link} вышла через {link:dark-portal}Темный портал{/link} в южные болота, и королевство {link:azeroth}Азерот{/link} приняло на себя всю тяжесть {link:first-war}Первой войны{/link}. Его фермы и деревни горели. {link:nak}Нак{/link}онец пал сам {link:stormwind-city}Штормград{/link}, и король {link:llane-wrynn}Ллейн Ринн{/link} был убит в собственной крепости. Сэр {link:anduin-lothar}Андуин Лотар{/link} увел уцелевших через море в {link:lordaeron}Лордерон{/link}, и среди них был юный сын короля, {link:varian-wrynn}Вариан{/link}.
• {b}Вторая война.{/b} Предостережение, которое привез Лотар, побудило короля {link:terenas-menethil}Теренаса Менетила{/link} созвать {link:alliance}Альянс Лордерона{/link}. Изгнанники Штормграда сражались во {link:second-war}Второй войне{/link} рядом с северными королевствами, пока Орда не была разбита.
• {b}Восстановление.{/b} Изгнанники вернулись домой, к руинам. Вариан был коронован, а {link:stonemasons-guild}Гильдия каменщиков{/link} заново подняла город из обломков. Когда {link:house-of-nobles}Палата знати{/link} отказалась платить каменщикам, улицы охватил бунт, и в этом хаосе погибла королева {link:tiffin-wrynn}Тиффин Ринн{/link}. Каменщиков изгнали, и из них родилось {link:defias-brotherhood}Братство Справедливости{/link}.
• {b}Третья война.{/b} Пока чума уничтожала Лордерон, худшие беды {link:third-war}Третьей войны{/link} миновали Штормград. Когда северное королевство пало, Штормград стал первой силой Альянса.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:stormwind-city}Штормград{/link} — королевство без короля. {link:varian-wrynn}Вариан Ринн{/link} исчез, и никто не может сказать, куда он пропал. Верховный лорд {link:bolvar-fordragon}Болвар Фордрагон{/link} правит как регент от имени малолетнего принца {link:anduin-wrynn}Андуина Ринна{/link}. При дворе леди {link:katrana-prestor}Катрана Престор{/link} завоевала слух знати и немалую долю доверия регента. Войско ушло далеко от дома, и сердце королевства приходится удерживать малочисленным гарнизонам и добровольцам. {link:westfall}Западный Край{/link} достался Братству Справедливости. {link:riverpaw-gnolls}Гноллы{/link} и {link:kobolds}кобольды{/link} разоряют {link:elwynn-forest}Элвиннский лес{/link}, {link:blackrock-clan}орки клана Черной горы{/link} теснят {link:redridge-mountains}Красногорье{/link}, а в Сумеречном лесу бродят мертвецы. Агенты {link:si-7}SI:7{/link} трудятся в тенях, но бед у державы много, а защитников мало.]=],
		},
	},
})

Translate("ruRU", "arathor", {
	title = "Аратор",
	sections = {
		{
			title = "Обзор",
			text = [=[Аратор был первой державой {link:humans}людей{/link}. Он был выкован в войне с троллями, и его спас союз с эльфами. От него произошли все королевства людей на севере и на юге. Самого Аратора нет уже больше тысячи лет, но его кровь и его знамена помнят всюду, где правят люди.]=],
		},
		{
			title = "Истоки",
			text = [=[Почти за три тысячи лет до Темного портала племена людей севера были разобщены и воевали друг с другом. {link:trolls}Тролли{/link} Амани совершали на них безжалостные набеги. Тогда {link:thoradin}Торадин{/link}, военный вождь племени {link:arathi-highlands}Арати{/link}, решил, что люди должны объединиться или погибнуть. Браком, обещанием и мечом он собрал племена под одним знаменем. Он назвал свою державу Аратором и воздвиг ее столицу, город-крепость {link:stromgarde-keep}Стром{/link}, на нагорье, которое до сих пор носит имя Арати.]=],
		},
		{
			title = "История",
			text = [=[• {b}Войны с троллями.{/b} Когда тролли Амани обрушились на {link:quel-thalas}Кель'Талас{/link}, эльфы отправили послов в {link:stromgarde-keep}Стром{/link}. В обмен на мечи Аратора они согласились обучить сто человек путям {link:arcane-magic}магии{/link}. Вместе эльфы и люди сокрушили троллей Амани у подножия {link:alterac-mountains}Альтерак{/link}ских гор. {link:troll-wars}Войны с троллями{/link} закончились, и эльфы поклялись в вечной дружбе роду, который основал {link:thoradin}Торадин{/link}.
• {b}Расселение.{/b} После правления Торадина народ Аратора расселился далеко за пределы столицы. Он основал {link:dalaran}Даларан{/link}, гавани {link:gilneas}Гилнеаса{/link}, островную державу {link:kul-tiras}Кул Тирас{/link}, горную твердыню Альтерак и богатые земли {link:lordaeron}Лордерона{/link}. Каждый город становился сильнее, и каждый все больше был сам себе хозяином.
• {b}Распад.{/b} Город Стром, бедный землей и торговлей, медленно терял власть. Его знатные семьи перебрались на север, в Лордерон. Последние наследники рода {link:arathi-highlands}Арати{/link} уплыли на юг и основали королевство, которое стало {link:kingdom-of-stormwind}королевством Штормград{/link}. Стром остался нескольким правящим домам, и они переименовали его в Стромгард. Империя стала семью королевствами.]=],
		},
		{
			title = "Наши дни",
			text = [=[Аратор живет только в своих наследниках. Семь королевств однажды были соединены снова, в {link:alliance}Альянс{/link}е {link:lordaeron}Лордерон{/link}а, и во главе его стоял {link:anduin-lothar}Андуин Лотар{/link}, последний из крови вождя {link:thoradin}Торадин{/link}а. Сегодня нагорье вокруг старой столицы — земля руин, за которую бьются {link:orcs}орк{/link}и, тролли, {link:ogres}огр{/link}ы и разбойники {link:syndicate}Синдиката{/link}.]=],
		},
	},
})

Translate("ruRU", "lordaeron", {
	title = "Лордерон",
	sections = {
		{
			title = "Обзор",
			text = [=[Лордерон был могущественнейшим из королевств людей. Из своей столицы в {link:tirisfal-glades}Тирисфаль{/link}ских лесах его короли правили северными землями и вели {link:alliance}Альянс{/link}, который спас людей во Второй войне. Он пал в Третью войну, преданный изнутри собственным принцем. Теперь его земли — царство мертвых.]=],
		},
		{
			title = "Истоки",
			text = [=[Во времена {link:arathor}Аратора{/link} поселенцы заняли плодородные {link:tirisfal-glades}Тирисфальские леса{/link} и назвали эту землю в честь Лордейна, полководца Войн с троллями. Когда {link:stromgarde-keep}Стром{/link} пришел в упадок, многие его знатные семьи перенесли свои владения на север, на эти богатые поля. Они сделали Лордерон самостоятельным королевством, и его границы быстро росли. Лордерон был также землей веры. Паломники приходили издалека в его монастыри в поисках исцеления и мудрости в {link:holy-light}Свете{/link}.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:second-war}Вторая война{/link}.{/b} Когда сэр {link:anduin-lothar}Андуин Лотар{/link} привел на север уцелевших жителей {link:stormwind-city}Штормград{/link}а, их принял король {link:terenas-menethil}Теренас Менетил{/link}. Затем он созвал правителей королевств людей и основал {link:alliance}Альянс Лордерона{/link}. Под началом Лотара, который стал его полководцем, Альянс отбросил {link:horde}Орду{/link} назад, за {link:dark-portal}Темный портал{/link}.
• {b}Тревожный мир.{/b} Побежденных {link:orcs}орк{/link}ов держали в лагерях для пленных по всему Лордерону, и это стоило очень дорого. Это бремя раскололо Альянс. {link:gilneas}Гилнеас{/link}, {link:stromgarde-keep}Стромгард{/link} и {link:quel-thalas}Кель'Талас{/link} покинули его, и королевство ослабло.
• {b}Чума.{/b} В {link:third-war}Третью войну{/link} {link:cult-of-the-damned}Культ Проклятых{/link} распространил чуму через зерно северных земель, и мертвые восстали тысячами. Принц {link:arthas-menethil}Артас Менетил{/link} сжег зачумленный город Стратхольм в дни {link:culling-of-stratholme}Очищения{/link}, а затем погнался за хозяевами чумы в Нордскол. Он вернулся рыцарем смерти {link:scourge}Плети{/link} и убил своего отца на его троне. Это и было {link:fall-of-lordaeron}падение Лордерона{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Лордерон — королевство трупов. {link:scourge}Плеть{/link} удерживает Чумные земли. Под руинами столицы {link:forsaken}Отрекшиеся{/link}, которых ведет {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link}, сделали своим домом {link:undercity}Подгород{/link}. {link:scarlet-crusade}Алый орден{/link} сжигает всех, кого подозревает в чуме, а {link:argent-dawn}Серебряный Рассвет{/link} противостоит Плети рядом с любым, кто готов помочь. Ни один король живых здесь больше не правит.]=],
		},
	},
})

Translate("ruRU", "gilneas", {
	title = "Гилнеас",
	sections = {
		{
			title = "Обзор",
			text = [=[Гилнеас — гордое королевство людей на суровом полуострове к югу от Серебряного бора. Его народ вынослив и привык полагаться на себя, а его войско некогда было одним из сильнейших среди семи королевств. После Второй войны его король отгородил свою державу от мира {link:ogres}огр{/link}омной стеной. Что происходит за этой стеной, не может сказать ни один чужак.]=],
		},
		{
			title = "Истоки",
			text = [=[Гилнеас был одним из городов-государств, которые основал народ {link:arathor}Аратора{/link} после Войн с троллями. Его поселенцы построили вдоль побережья крепкие гавани, а его самые отважные мореходы затем основали {link:kul-tiras}Кул Тирас{/link}. Не в силах соперничать с кул-тирасским флотом, Гилнеас обратился к торговле и ратному делу. Его солдат считали равными любым в Араторе.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:second-war}Вторая война{/link}.{/b} Король {link:genn-greymane}Генн Седогрив{/link} вступил в Альянс Лордерона без особой любви к нему. Он считал, что Гилнеас способен защитить себя сам, и держал свои войска поближе к дому.
• {b}{link:the-greymane-wall}Стена Седогрива{/link}.{/b} После войны его разгневали расходы на лагеря для пленных {link:orcs}орк{/link}ов. Седогрив вывел свое королевство из {link:alliance}Альянса{/link}. Затем он возвел {link:ogres}огр{/link}омную стену вдоль северной границы королевства и закрыл ее ворота. Стена прошла через земли его собственной знати и оставила снаружи такие селения, как {link:pyrewood-village}Деревня Погребальных Костров{/link} и {link:ambermill}Янтарная мельница{/link}.
• {b}{link:third-war}Третья война{/link}.{/b} Когда чума прокатилась по {link:lordaeron}Лордерону{/link}, ворота королевства остались закрытыми. Ни одно войско не вышло с юга на помощь гибнущему королевству.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:the-greymane-wall}Стена Седогрива{/link} стоит до сих пор, и ее ворота по-прежнему закрыты. За ней, в {link:silverpine-forest}Серебряном бору{/link}, {link:scourge}Плеть{/link} и {link:forsaken}Отрекшиеся{/link} сражаются за старые земли севера. Жителям деревень, оставшихся снаружи стены, приходится заботиться о себе самим. Что сталось с королевством внутри, неизвестно.]=],
		},
	},
})

Translate("ruRU", "kul-tiras", {
	title = "Кул Тирас",
	sections = {
		{
			title = "Обзор",
			text = [=[Кул Тирас — островное королевство в Великом море, к западу от Каз Модана. Это держава моряков и корабелов, и ее флот некогда был величайшим в мире. Из дома Праудмуров выходили ее адмиралы, а из ее гаваней — флоты, которые несли {link:alliance}Альянс{/link} на войну.]=],
		},
		{
			title = "Истоки",
			text = [=[Мореходы из {link:gilneas}Гилнеаса{/link} открыли на юге большой остров, богатый рудой и лесом. Некоторые из них остались и основали там морскую заставу, которая выросла в отдельное королевство. Кул Тирас процветал за счет рыболовства и торговли. Его торговые флоты ходили вдоль всех берегов известного мира, и во времена {link:arathor}Аратора{/link} он владел крупнейшим флотом империи.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:second-war}Вторая война{/link}.{/b} Лорд-адмирал {link:daelin-proudmoore}Делин Праудмур{/link} привел флоты Кул Тираса в {link:alliance}Альянс Лордерона{/link}. Его корабли сражались с орочьими флотами на морях и снабжали войска Альянса. Королевство заплатило тяжелую цену кораблями и людьми.
• {b}Тревожный мир.{/b} Когда после войны Альянс ослаб, Кул Тирас остался ему верен, но все больше и больше уходил в собственные дела.
• {b}{link:theramore-isle}Терамор{/link}.{/b} После {link:third-war}Третьей войны{/link} дочь лорда-адмирала, {link:jaina-proudmoore}Джайна Праудмур{/link}, увела уцелевших жителей севера в {link:kalimdor}Калимдор{/link}, где заключила мир с {link:orcs}орк{/link}ами, которых ведет {link:thrall}Тралл{/link}. Делин не пожелал с этим смириться. Он пришел со своим флотом, чтобы уничтожить {link:horde}Орду{/link}, и был убит в бою перед стенами Терамора.]=],
		},
		{
			title = "Наши дни",
			text = [=[Кул Тирас лежит далеко за морем и мало участвует в делах материка. На побережьях {link:kalimdor}Калимдор{/link}а кул-тирасские морские пехотинцы все еще удерживают {link:northwatch-hold}Крепость Северной Стражи{/link} в {link:the-barrens}Степях{/link} и {link:tiragarde-keep}Крепость Тирагард{/link} в {link:durotar}Дуротаре{/link}. Они не простили Орде смерти своего адмирала.]=],
		},
	},
})

Translate("ruRU", "dalaran", {
	title = "Даларан",
	sections = {
		{
			title = "Обзор",
			text = [=[Даларан — {link:city-of-dalaran}город магов{/link}. Он был первым городом-государством {link:arathor}Аратора{/link}, который стал править собой сам, и больше двух тысяч лет был сердцем магии людей. Его фиолетовые башни поднимались над берегами озера Лордамер, пока {link:scourge}Плеть{/link} и {link:burning-legion}Пылающий Легион{/link} не обрушили их. Теперь Даларан вновь поднялся в {link:alterac-mountains}Альтерак{/link}ских горах, и его маги — его владыки.]=],
		},
		{
			title = "Истоки",
			text = [=[Даларан начинался как торговая застава в середине {link:arathor}Аратор{/link}а. Он быстро рос и стал прибежищем магов империи, которым простой народ не доверял. При маге Ардогане город добился свободы от столицы империи, и им стали управлять чародеи. Их безрассудная магия привлекла внимание демонов. Чтобы тайно сражаться с ними, маги Даларана и эльфы {link:quel-thalas}Кель'Таласа{/link} основали {link:shadow-council}Совет{/link} Тирисфаля, Хранители которого поколениями защищали мир. Со временем маги города образовали совет {link:kirin-tor}Кирин-Тор{/link}, который и стал им править.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:second-war}Вторая война{/link}.{/b} Даларан вступил в {link:alliance}Альянс Лордерона{/link} и послал своих магов сражаться с {link:orcs}орк{/link}ами. После войны его волшебники следили за Темным порталом из Крепости Стражей Пустоты.
• {b}{link:third-war}Третья война{/link}.{/b} Некромант {link:kel-thuzad}Кел'Тузад{/link}, некогда маг Даларана, основал {link:cult-of-the-damned}Культ Проклятых{/link}. По его велению {link:arthas-menethil}Артас Менетил{/link} повел {link:scourge}Плеть{/link} на город и захватил книгу заклинаний, которую оставил {link:medivh}Медив{/link}. С ее помощью в мир был призван {link:archimonde}Архимонд{/link}. Повелитель демонов сокрушил Даларан одним заклинанием и оставил его в руинах.
• {b}Восстановление.{/b} Уцелевшие маги вернулись на руины. Они воздвигли над городом {link:ogres}огр{/link}омную фиолетовую преграду и отстроили его за этим щитом, сокрытый от мира.]=],
		},
		{
			title = "Наши дни",
			text = [=[Даларан стоит отстроенный в {link:alterac-mountains}Альтерак{/link}ских горах, и его преграды больше нет. Никто за пределами {link:kirin-tor}Кирин-Тор{/link}а пока не может сказать, почему она пала. Город вновь открыт, и его улицы полны магов, купцов и банкиров. Но внутри не все благополучно. Чары дают сбой, магические создания выходят из-под власти, а на улицах шевелится демоническая сила. Маги Кирин-Тора горды и неохотно признают, что им нужна помощь.]=],
		},
	},
})

Translate("ruRU", "kirin-tor", {
	title = "Кирин-Тор",
	sections = {
		{
			title = "Обзор",
			text = [=[Кирин-Тор — маги {link:dalaran}Даларана{/link} и правители этого города. Они хранители магии людей: ее ученые, ее судьи и ее стражи. Они издавна притязают на право надзирать за каждым заклинанием, сотворенным в землях людей, и ревниво берегут свои тайны.]=],
		},
		{
			title = "Истоки",
			text = [=[Когда империя {link:arathor}Аратор{/link} начала распадаться, маги {link:dalaran}Даларан{/link}а образовали общину, чтобы изучить и записать каждое заклинание и каждую магическую реликвию, известные людям. Этой общиной и был Кирин-Тор. Она выросла в правящий орден города, во главе которого стоял совет его величайших членов. Из своей Аметистовой цитадели они судили, какую магию можно применять, а какую должно запретить.]=],
		},
		{
			title = "История",
			text = [=[• {b}Хранители.{/b} Веками Кирин-Тор трудился вместе с {link:shadow-council}Совет{/link}ом Тирисфаля, который избирал Хранителей, втайне сражавшихся с демонами. Последним Хранителем был {link:medivh}Медив{/link}.
• {b}{link:second-war}Вторая война{/link}.{/b} Маги Кирин-Тора сражались за {link:alliance}Альянс Лордерона{/link}. После войны они построили {link:nethergarde-keep}Крепость Стражей Пустоты{/link} возле {link:dark-portal}Темного портала{/link}, чтобы следить за разоренной землей по ту сторону.
• {b}{link:third-war}Третья война{/link}.{/b} Кирин-Тор изгнал мага {link:kel-thuzad}Кел'Тузада{/link} за изучение некромантии. Тот вернулся главой {link:cult-of-the-damned}Культа Проклятых{/link}, и его чума уничтожила {link:lordaeron}Лордерон{/link}. Глава ордена, верховный маг {link:brother-anton}Антон{/link}идас, был убит, когда {link:scourge}Плеть{/link} взяла {link:dalaran}Даларан{/link}.
• {b}Воргены.{/b} Один из магов ордена, верховный маг {link:archmage-arugal}Аругал{/link}, призвал свирепых воргенов, чтобы сражаться с Плетью в {link:silverpine-forest}Серебряном бору{/link}. Они оказались проклятием не меньшим, чем нежить. Ныне Аругал владеет Крепостью Темного Клыка, и говорят, что он лишился рассудка.]=],
		},
		{
			title = "Наши дни",
			text = [=[Маги Кирин-Тора отстроили {link:dalaran}Даларан{/link} в {link:alterac-mountains}Альтерак{/link}ских горах, и его преграда пала. В городе их заклинания дают осечку, а их создания срываются с привязи, и они с трудом удерживают власть над собственными улицами. Их маги по-прежнему несут стражу в Крепости Стражей Пустоты, а некоторые из них стоят в {link:theramore-isle}Терамор{/link}е рядом с его правительницей, {link:jaina-proudmoore}Джайной Праудмур{/link}.]=],
		},
	},
})

Translate("ruRU", "quel-thalas", {
	title = "Кель'Талас",
	sections = {
		{
			title = "Обзор",
			text = [=[Кель'Талас — королевство {link:high-elves}высших эльфов{/link} в северных лесах {link:lordaeron}Лордерон{/link}а. Тысячи лет это была страна вечной весны, которую питала магия Солнечного Колодца. В {link:third-war}Третью войну{/link} {link:scourge}Плеть{/link} прошла через его врата и осквернила его священный источник. То, что осталось от королевства, лежит безмолвное и далекое.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:great-sundering}Великого Раскола{/link} отряд изгнанников-высокорожденных покинул {link:kalimdor}Калимдор{/link}: {link:night-elves}ночные эльфы{/link} изгнали их за любовь к магии. Их вел Дат'Ремар Солнечный Скиталец; они пересекли море и поселились на севере {link:eastern-kingdoms}Восточных королевств{/link}. Там они основали Кель'Талас и создали Солнечный Колодец, источник тайной силы. По лесам расставили рунные камни, чтобы скрыть их магию от демонов, которых она могла привлечь.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:troll-wars}Войны с троллями{/link}.{/b} {link:trolls}Тролли{/link} Амани едва не захватили молодое королевство. Эльфы попросили помощи у {link:arathor}Аратора{/link} и в обмен на его войска обучили магии сотню людей. Вместе они сокрушили троллей Амани, и эльфы поклялись в дружбе роду вождя {link:thoradin}Торадин{/link}а.
• {b}{link:second-war}Вторая война{/link}.{/b} Когда {link:horde}Орда{/link} и тролли Амани подожгли леса, король Анастериан Солнечный Скиталец исполнил старый долг и вступил в {link:alliance}Альянс Лордерона{/link}. После войны он рассудил, что Альянс подвел его народ, и вышел из него.
• {b}{link:third-war}Третья война{/link}.{/b} Принц {link:arthas-menethil}Артас Менетил{/link} повел {link:scourge}Плеть{/link} на север. Генерал следопытов {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link} сражалась с ним у каждых ворот и была убита. Артас убил короля эльфов и использовал Солнечный Колодец, чтобы воскресить личом некроманта: это был {link:kel-thuzad}Кел'Тузад{/link}. Сердце эльфийской державы было осквернено.]=],
		},
		{
			title = "Наши дни",
			text = [=[Кель'Талас лежит за Чумными землями, отрезанный от юга {link:scourge}Плеть{/link}ю. Вестей оттуда приходит мало. {link:high-elves}Высшие эльфы{/link}, оставшиеся в южных землях, живут небольшими разрозненными отрядами, как следопыты Сторожки {link:quel-danil-lodge}Кель'Данил{/link} во {link:the-hinterlands}Внутренних землях{/link}. Многие из них скорбят о доме, которого, быть может, больше не увидят.]=],
		},
	},
})

Translate("ruRU", "alliance", {
	title = "Альянс",
	aliases = { "Альянс Лордерона" },
	sections = {
		{
			title = "Обзор",
			text = [=[Альянс — союз народов, связанных вместе против общих врагов. В нем стоят люди, {link:dwarves}дворфы{/link}, {link:gnomes}гномы{/link} и {link:night-elves}ночные эльфы{/link}. Он родился во Вторую войну, чтобы противостоять орочьей {link:horde}Орде{/link}, и с тех пор был разрушен и создан заново. Сегодня его величайшие силы — {link:kingdom-of-stormwind}королевство Штормград{/link} и {link:kingdom-of-ironforge}королевство Стальгорн{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Когда в {link:first-war}Первую войну{/link} пал {link:stormwind-city}Штормград{/link}, сэр {link:anduin-lothar}Андуин Лотар{/link} привел уцелевших в {link:lordaeron}Лордерон{/link} и предупредил, что {link:horde}Орда{/link} придет на север. Король {link:terenas-menethil}Теренас Менетил{/link} внял ему. Он созвал правителей королевств людей и связал их в Альянс Лордерона, верховным полководцем которого стал Лотар. К нему примкнули также {link:dwarves}дворф{/link}ы {link:ironforge}Стальгорн{/link}а, {link:gnomes}гном{/link}ы {link:gnomeregan}Гномрегана{/link} и высшие эльфы {link:quel-thalas}Кель'Таласа{/link}.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:second-war}Вторая война{/link}.{/b} Альянс встретил Орду по всему северу и оттеснил ее к Вершине Черной горы. {link:anduin-lothar}Лотар{/link} пал в последних битвах, и к окончательной победе войско привел его помощник {link:turalyon}Туралион{/link}. Уцелевших {link:orcs}орк{/link}ов согнали в лагеря для пленных.
• {b}{link:great-sundering}Раскол{/link}.{/b} Расходы на лагеря и старые обиды раскололи Альянс. {link:gilneas}Гилнеас{/link}, {link:stromgarde-keep}Стромгард{/link} и {link:quel-thalas}Кель'Талас{/link} покинули его. {link:alterac-mountains}Альтерак{/link} к тому времени уже предал его Орде и был лишен короны.
• {b}{link:third-war}Третья война{/link}.{/b} Чума и {link:scourge}Плеть{/link} уничтожили {link:lordaeron}Лордерон{/link}. {link:jaina-proudmoore}Джайна Праудмур{/link} увела уцелевших на запад, в {link:kalimdor}Калимдор{/link}, где люди, орки и ночные эльфы сражались бок о бок в {link:battle-of-mount-hyjal}битве у горы Хиджал{/link}.
• {b}Новый Альянс.{/b} За прошедшие годы {link:stormwind-city}Штормград{/link} поднял знамя, которое выронил Лордерон. Рядом с ним стоит {link:ironforge}Стальгорн{/link}, {link:gnomes}гном{/link}ы павшего {link:gnomeregan}Гномреган{/link}а нашли приют у {link:dwarves}дворф{/link}ов, и к Альянсу примкнули ночные эльфы {link:darnassus}Дарнасса{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Альянс силен на бумаге и растянут до предела на деле. Король {link:varian-wrynn}Вариан Ринн{/link} исчез, и {link:stormwind-city}Штормград{/link}ом как регент правит верховный лорд {link:bolvar-fordragon}Болвар Фордрагон{/link}. {link:ironforge}Стальгорн{/link}ом правит король {link:magni-bronzebeard}Магни Бронзобород{/link}. Ночных эльфов ведет {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link}, а {link:theramore-isle}Терамор{/link} удерживает {link:jaina-proudmoore}Джайна Праудмур{/link}. Их солдаты сражаются с Ордой в Ясеневом лесу и в Степях, с {link:scourge}Плеть{/link}ю в {link:lordaeron}Лордерон{/link}е и с дюжиной врагов помельче у себя дома. О мире с {link:orcs}орк{/link}ами говорят часто, а верят в него редко.]=],
		},
	},
})

Translate("ruRU", "horde", {
	title = "Орда",
	sections = {
		{
			title = "Обзор",
			text = [=[Орда — союз {link:orcs}орк{/link}ов и их союзников: {link:darkspear-trolls}троллей Черного Копья{/link}, {link:tauren}тауренов{/link} и {link:forsaken}Отрекшихся{/link}. Она родилась в другом мире как орудие демонов. Она перешла в {link:azeroth}Азерот{/link}, сжигала королевства и была разбита. Затем она возродилась под началом молодого вождя как народ, ищущий свободы. Ее столица — {link:orgrimmar}Оргриммар{/link} в красной земле {link:durotar}Дуротар{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[На Дреноре {link:orcs}орк{/link}и были гордым народом кланов и шаманов. Демон {link:kil-jaeden}Кил'джеден{/link} из {link:burning-legion}Пылающего Легиона{/link} задумал сделать их своим оружием. Сначала через шамана {link:ner-zhul}Нер'зула{/link}, а затем через чернокнижника {link:gul-dan}Гул'дана{/link} он научил их магии Скверны. {link:nak}Нак{/link}онец вожди кланов испили кровь демона {link:mannoroth}Маннорот{/link}а, и жгучая жажда крови привязала их к Легиону. Объединившись в одну Орду, они истребили дренеев, и их мир зачах у них под ногами.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:first-war}Первая война{/link}.{/b} Через {link:dark-portal}Темный портал{/link} Орда вторглась в королевство {link:azeroth}Азерот{/link} и уничтожила его. {link:stormwind-city}Штормград{/link} пал, и король {link:llane-wrynn}Ллейн Ринн{/link} был убит.
• {b}{link:second-war}Вторая война{/link}.{/b} Вождем Орды стал {link:orgrim-doomhammer}Оргрим Молот Рока{/link}, и она двинулась на север с {link:ogres}огр{/link}ами, троллями Амани, гоблинами и порабощенными красными драконами. {link:alliance}Альянс{/link} разбил ее, и большинство уцелевших {link:orcs}орк{/link}ов заперли в лагерях для пленных.
• {b}Новая Орда.{/b} В лагерях орки впали в странное оцепенение. Молодой орк, выросший рабом, {link:thrall}Тралл{/link}, вырвался на волю, постиг старые пути шаманов и освободил свой народ. Молот Рока погиб, сражаясь рядом с ним, и передал ему свой молот и свой титул.
• {b}{link:third-war}Третья война{/link}.{/b} Вняв пророку {link:medivh}Медиву{/link}, Тралл увел Орду в {link:kalimdor}Калимдор{/link}. Там он завоевал дружбу племени Черного Копья и {link:tauren}таурен{/link}ов, которых ведет {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link}. {link:grom-hellscream}Гром Адский Крик{/link} убил демона {link:mannoroth}Маннорот{/link}а и освободил орков от проклятия его крови. Орда сражалась рядом с Альянсом в {link:battle-of-mount-hyjal}битве у горы Хиджал{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:thrall}Тралл{/link} правит как вождь из {link:orgrimmar}Оргриммар{/link}а, названного в честь прежнего вождя, Молота Рока. {link:cairne-bloodhoof}Кэрн{/link} ведет {link:tauren}таурен{/link}ов из {link:thunder-bluff}Громового Утеса{/link}, {link:vol-jin}Вол'джин{/link} ведет племя Черного Копья, а {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link} привела на сторону Орды Отрекшихся {link:lordaeron}Лордерон{/link}а. Мир с {link:theramore-isle}Терамор{/link}ом держится, но едва-едва. В {link:ashenvale}Ясеневом лесу{/link} {link:orcs}орк{/link}и рубят деревья в чащах ночных эльфов, и за это льется кровь. Кул-тирасские морские пехотинцы стерегут побережья, {link:centaurs}кентавр{/link}ы и {link:quilboar}свинобраз{/link}ы теснят каждую границу, а демонический культ {link:burning-blade}Пылающего Клинка{/link} гноится в самом {link:durotar}Дуротар{/link}е.]=],
		},
	},
})

Translate("ruRU", "burning-legion", {
	title = "Пылающий Легион",
	sections = {
		{
			title = "Обзор",
			text = [=[Пылающий Легион — {link:ogres}огр{/link}омное войско демонов, которое опустошило бесчисленные миры. Его господин — {link:sargeras}Саргерас{/link}, падший титан, который некогда защищал творение, а ныне стремится его уничтожить. Трижды Легион тянулся к {link:azeroth}Азероту{/link}. Трижды он был отброшен, и страшной ценой.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:sargeras}Саргерас{/link} некогда был величайшим защитником титанов, творцов миров. За века войны с демонами из {link:krueg-skullsplitter}Круг{/link}оверти Пустоты он пришел к убеждению, что все творение порочно и должно быть сожжено. Он обратился против собственного рода и собрал для этого войско демонов. Среди первых, кого он совратил, были эредары, предводители которых, {link:kil-jaeden}Кил'джеден{/link} и {link:archimonde}Архимонд{/link}, стали его главными помощниками.]=],
		},
		{
			title = "История",
			text = [=[• {b}Война древних.{/b} {link:queen-azshara}Королева Азшара{/link} и ее высокорожденные привели Легион в мир через {link:well-of-eternity}Источник Вечности{/link}. {link:night-elves}Ночные эльфы{/link}, которых вел {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, дали отпор в {link:war-of-the-ancients}Войне древних{/link}. Уничтожение Источника раскололо континент в {link:great-sundering}Великом Расколе{/link} и отрезало демонов.
• {b}Орда.{/b} Затем {link:kil-jaeden}Кил'джеден{/link} совратил {link:orcs}орк{/link}ов Дренора и сделал их оружием. Выкованная им {link:horde}Орда{/link} была брошена на {link:azeroth}Азерот{/link} в {link:first-war}Первой войне{/link} и во {link:second-war}Второй войне{/link}.
• {b}{link:third-war}Третья война{/link}.{/b} Легион создал {link:scourge}Плеть{/link}, чтобы она подготовила путь. Чума убила {link:lordaeron}Лордерон{/link}, и сам {link:archimonde}Архимонд{/link} был призван в мир в {link:dalaran}Даларан{/link}е. Он двинулся к Древу Жизни, {link:nordrassil}Нордрассилу{/link}. В {link:battle-of-mount-hyjal}битве у горы Хиджал{/link} ночные эльфы, люди и орки удерживали его достаточно долго, чтобы духи предков уничтожили его.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:archimonde}Архимонд{/link} мертв, но Легион не ушел из {link:azeroth}Азерот{/link}а. Демоны все еще рыщут в оскверненных чащах {link:felwood}Оскверненного леса{/link}, в руинах {link:azshara}Азшары{/link} и в глуши {link:desolace}Пустошей{/link}. Культ {link:burning-blade}Пылающего Клинка{/link} втайне служит им среди {link:orcs}орк{/link}ов. В {link:blasted-lands}Выжженных землях{/link} маги Крепости Стражей Пустоты следят за {link:dark-portal}Темным порталом{/link} и ждут любого знака их возвращения.]=],
		},
	},
})

Translate("ruRU", "scourge", {
	title = "Плеть",
	sections = {
		{
			title = "Обзор",
			text = [=[Плеть — войско нежити, поднятое чумой, которым правит Король-лич во льдах Нордскола. В {link:third-war}Третью войну{/link} она уничтожила королевство {link:lordaeron}Лордерон{/link}, осквернила {link:quel-thalas}Кель'Талас{/link} и сровняла с землей {link:dalaran}Даларан{/link}. Она до сих пор удерживает большую часть севера и до сих пор алчет живых.]=],
		},
		{
			title = "Истоки",
			text = [=[После того как {link:orcs}орк{/link}и подвели его, {link:kil-jaeden}Кил'джеден{/link} из {link:burning-legion}Пылающего Легиона{/link} покарал их старого шамана {link:ner-zhul}Нер'зула{/link}. Он сорвал с орка тело и заключил его дух в доспехи, запечатанные в глыбе льда. Затем он низверг его в Нордскол и нарек Королем-личом. Его задачей было распространить чуму нежити по землям людей и подготовить их для Легиона. Со своего Ледяного Трона Король-лич дотягивался разумом до живых и привлекал на свою сторону честолюбивых и отчаявшихся.]=],
		},
		{
			title = "История",
			text = [=[• {b}Чума.{/b} Маг {link:kel-thuzad}Кел'Тузад{/link} услышал зов Короля-лича и основал {link:cult-of-the-damned}Культ Проклятых{/link}. Через культ чума была распространена в зерне северного {link:lordaeron}Лордерон{/link}а. Те, кто ел его, умирали и восставали нежитью.
• {b}Падение.{/b} Принц {link:arthas-menethil}Артас Менетил{/link} шел по следу чумы до Нордскола. Там он взял рунический клинок, Ледяную Скорбь, и стал защитником Короля-лича. Он вернулся, чтобы убить своего отца и отдать Лордерон мертвым. Затем он провел Плеть через {link:quel-thalas}Кель'Талас{/link}, где воскресил личом некроманта Кел'Тузада, и дальше, к {link:dalaran}Даларан{/link}у, где был призван повелитель демонов {link:archimonde}Архимонд{/link}.
• {b}Разорванные цепи.{/b} После того как Архимонд пал на горе Хиджал, хватка Короля-лича ослабла. Многие из нежити вырвались на волю, и {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link} повела их как {link:forsaken}Отрекшихся{/link}. Артас ушел на север, на помощь Королю-личу.]=],
		},
		{
			title = "Наши дни",
			text = [=[Плеть по-прежнему правит Чумными землями. {link:kel-thuzad}Кел'Тузад{/link} повелевает от имени Короля-лича, а его слуги удерживают разрушенный город Стратхольм, школу некромантии в Некроситете и многие павшие городки. Зачумленные твари бродят по лесам, а поганища стерегут мертвые земли. Против них стоят {link:forsaken}Отрекшиеся{/link}, {link:scarlet-crusade}Алый орден{/link} и {link:argent-dawn}Серебряный Рассвет{/link}, которые больше ни в чем не согласны между собой.]=],
		},
	},
})

Translate("ruRU", "cult-of-the-damned", {
	title = "Культ Проклятых",
	sections = {
		{
			title = "Обзор",
			text = [=[Культ Проклятых — живое жречество {link:scourge}Плети{/link}. Его члены поклоняются Королю-личу и служат ему добровольно, в надежде на вечную жизнь после смерти. Именно культ принес чуму в {link:lordaeron}Лордерон{/link}, и его некроманты до сих пор поднимают мертвых именем Короля-лича.]=],
		},
		{
			title = "Истоки",
			text = [=[Культ основал {link:kel-thuzad}Кел'Тузад{/link}, маг совета {link:kirin-tor}Кирин-Тор{/link}, изгнанный за запретное изучение некромантии. Он отправился в Нордскол и услышал голос Короля-лича. В {link:lordaeron}Лордерон{/link} он вернулся его пророком. Среди бедных и забытых жителей севера он проповедовал новое общество, где все будут равны и где смерть не будет концом. За ним пошли тысячи, и немногие понимали, к чему примкнули.]=],
		},
		{
			title = "История",
			text = [=[• {b}Чума.{/b} Культ распространил чуму нежити через амбары северного {link:lordaeron}Лордерон{/link}а. Из {link:ruins-of-andorhal}Андорал{/link}а зараженное зерно расходилось по деревням, и мертвые начали восставать.
• {b}Смерть и возвращение некроманта.{/b} Принц {link:arthas-menethil}Артас Менетил{/link} убил главу культа в Андорале; этим главой был {link:kel-thuzad}Кел'Тузад{/link}. После того как Артас сам перешел на службу Королю-личу, он отвез останки некроманта к Солнечному Колодцу {link:quel-thalas}Кель'Таласа{/link} и воскресил его личом.
• {b}Некроситет.{/b} Семья Баров отдала культу свою островную крепость {link:caer-darrow}Каэр Дарроу{/link}. Там, в Некроситете, культ обучает новых некромантов.]=],
		},
		{
			title = "Наши дни",
			text = [=[Культ остается сильным в Чумных землях. Его послушники служат в руинах Стратхольма и {link:ruins-of-andorhal}Андорал{/link}а. В Некроситете темный магистр Гандлинг учит некромантии тех, кто сам этого желает. Агенты культа по-прежнему ходят среди живых в поисках новых сторонников и новых способов распространить чуму.]=],
		},
	},
})

Translate("ruRU", "scarlet-crusade", {
	title = "Алый орден",
	sections = {
		{
			title = "Обзор",
			text = [=[Алый орден — воинствующий орден {link:holy-light}Света{/link}, поклявшийся уничтожить нежить {link:lordaeron}Лордерона{/link}. Он родился из горя Третьей войны и стал суровым и фанатичным. Орден не доверяет никому. Он охотится на {link:scourge}Плеть{/link}, но охотится и на {link:forsaken}Отрекшихся{/link}, и в каждом чужаке видит возможного разносчика чумы.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:fall-of-lordaeron}падения Лордерона{/link} орден паладинов, который основал {link:uther-the-lightbringer}Утер Светоносный{/link}, лежал разбитым, и многие его рыцари были мертвы. Уцелевшие собрались вокруг паладина старого ордена: это был верховный крестоносец Сайдан Датрохан. Они поклялись очистить {link:lordaeron}Лордерон{/link} от малейшего следа чумы и избрали своим цветом алый. Многие из тех, кто потерял из-за Плети все, стекались под их знамена.]=],
		},
		{
			title = "История",
			text = [=[• {b}Поход.{/b} Орден сражался с {link:scourge}Плеть{/link}ю по всему северу с великой отвагой и малой долей милосердия. Он укрепил {link:scarlet-monastery}Монастырь Алого ордена{/link} в {link:tirisfal-glades}Тирисфальских лесах{/link}, городок {link:hearthglen}Дольный Очаг{/link} и город {link:tyr-s-hand}Длань Тира{/link}.
• {b}Фанатики.{/b} Со временем рвение ордена обратилось в жестокость. Он начал истреблять всякого, кого подозревал в чуме, и его инквизиторов стали бояться среди живых. Некоторые его члены не могли вынести того, чем он стал. Они покинули его и основали {link:argent-dawn}Серебряный Рассвет{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Алый орден удерживает Монастырь в {link:tirisfal-glades}Тирисфаль{/link}ских лесах, где его рыцарей ведут верховный инквизитор {link:high-inquisitor-whitemane}Вайтмейн{/link} и командир Алого ордена {link:scarlet-commander-mograine}Могрейн{/link}. Его силы удерживают также {link:hearthglen}Дольный Очаг{/link} в {link:western-plaguelands}Западных Чумных землях{/link} и {link:tyr-s-hand}Длань Тира{/link} в {link:eastern-plaguelands}Восточных Чумных землях{/link}. Его дозоры сжигают Отрекшихся всюду, где находят их. Его рвение неподдельно, как и его сила. Служит ли он еще {link:holy-light}Свет{/link}у — вопрос, который его собственные члены больше не смеют задавать.]=],
		},
	},
})

Translate("ruRU", "argent-dawn", {
	title = "Серебряный Рассвет",
	sections = {
		{
			title = "Обзор",
			text = [=[Серебряный Рассвет — орден, поклявшийся защищать {link:azeroth}Азерот{/link} от {link:scourge}Плети{/link}, {link:burning-legion}Пылающего Легиона{/link} и любой иной силы, которая желает его уничтожить. Он стоит в стороне от королей и вождей. Он привечает всякого, кто готов сражаться с нежитью, какова бы ни была его раса или знамя, и потому числит среди своих друзей {link:orcs}орк{/link}ов, людей, {link:dwarves}дворф{/link}ов и даже Отрекшихся.]=],
		},
		{
			title = "Истоки",
			text = [=[Рассвет родился из {link:scarlet-crusade}Алого ордена{/link}. Когда орден стал фанатичным, некоторые его члены начали опасаться, что его предводители сбились с пути. {link:lord-maxwell-tyrosus}Лорд Максвелл Тиросус{/link} и другие отказались идти за ним дальше. Они покинули Алый орден и основали новый, верный учению {link:holy-light}Света{/link}, как они его понимали. Его первым предводителем был лорд Раймонд Джордж.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:bor-wildmane}Бор{/link}ьба на севере.{/b} С первых своих дней Серебряный Рассвет сражался с {link:scourge}Плеть{/link}ю по всем Чумным землям, часто с малым числом воинов и еще меньшими припасами.
• {b}Орден, открытый для всех.{/b} В отличие от Алого ордена, Рассвет не спрашивает, кем его союзники были при жизни. Он принимает помощь и {link:alliance}Альянса{/link}, и {link:horde}Орды{/link} и судит каждого только по делам.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:lord-maxwell-tyrosus}Лорд Максвелл Тиросус{/link} ведет Серебряный Рассвет из Часовни Последней Надежды в {link:eastern-plaguelands}Восточных Чумных землях{/link}. Его лагеря разбросаны по Чумным землям, а его посланники ждут в далеких городах, чтобы собирать союзников. Рассвет награждает тех, кто приносит доказательства того, что уничтожил мертвецов. Его члены говорят, что войну с {link:scourge}Плеть{/link}ю не выиграть ни одному народу в одиночку.]=],
		},
	},
})

Translate("ruRU", "defias-brotherhood", {
	title = "Братство Справедливости",
	aliases = { "Братство Справедливости" },
	sections = {
		{
			title = "Обзор",
			text = [=[Братство Справедливости — войско изгоев, которое захватило {link:westfall}Западный Край{/link} и разоряет земли {link:kingdom-of-stormwind}королевства Штормград{/link}. Его члены носят красные повязки и бьют из тени. Его ядро составляют каменщики, которые отстроили {link:stormwind-city}Штормград{/link} и так и не получили платы за свой труд. Они намерены взять то, что им причитается, а затем взять и сам город.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:second-war}Второй войны{/link} {link:stonemasons-guild}Гильдия каменщиков{/link}, главой которой был {link:edwin-vancleef}Эдвин ван Клиф{/link}, подняла {link:stormwind-city}Штормград{/link} из пепла. Когда их труд был окончен, {link:house-of-nobles}Палата знати{/link} отказалась им платить. Каменщики взбунтовались, и в этом хаосе была убита королева {link:tiffin-wrynn}Тиффин Ринн{/link}. Каменщиков изгнали из города. Их повел ван Клиф, и они ушли на запад, в холмы и поля Западного Края, и там стали Братством Справедливости.]=],
		},
		{
			title = "История",
			text = [=[• {b}Завоевание Западного Края.{/b} Пока войско было далеко, а корона молчала, Братство заняло {link:westfall}Западный Край{/link} почти без сопротивления. Его члены согнали фермеров с их земель и сделали своим оплотом деревню {link:moonbrook}Луноречье{/link}.
• {b}Рука Братства.{/b} Воры Братства проникли в {link:elwynn-forest}Элвиннский лес{/link}, {link:redridge-mountains}Красногорье{/link} и {link:duskwood}Сумеречный лес{/link}. Золото, украденное {link:kobolds}кобольд{/link}ами, переходит к их агентам, а на их кольцах стоит старый знак гильдии каменщиков.]=],
		},
		{
			title = "Наши дни",
			text = [=[Братство правит Западным Краем из тени. Под {link:moonbrook}Луноречье{/link}м, в Мертвых копях, каменщики, которых ведет {link:edwin-vancleef}ван Клиф{/link}, строят {link:ogres}огр{/link}омный корабль ради цели, которую держат в тайне. Их жатвенные големы работают на украденных полях, а их шайки держат дороги. Против них стоит лишь Народное ополчение Сторожевого холма, которое возглавляет {link:gryan-stoutmantle}Гриан Камнегрив{/link}. В штормградской темнице, Тюрьме, пленные члены Братства восстали и захватили камеры.]=],
		},
	},
})

Translate("ruRU", "stonemasons-guild", {
	title = "Гильдия каменщиков",
	sections = {
		{
			title = "Обзор",
			text = [=[Гильдия каменщиков была братством строителей, которые заново возвели {link:stormwind-city}Штормград{/link} после Второй войны. Их мастерство дало городу белые стены и великие башни. {link:illidan-stormrage}Предатель{/link}ство со стороны королевства обратило его лучших каменщиков в его опаснейших врагов.]=],
		},
		{
			title = "Истоки",
			text = [=[Когда изгнанники {link:stormwind-city}Штормград{/link}а вернулись из {link:lordaeron}Лордерона{/link}, они нашли свою столицу в руинах. Труд по ее восстановлению лег на каменщиков. Их глава, {link:edwin-vancleef}Эдвин ван Клиф{/link}, был мастером редких дарований, и под его началом гильдия за годы совершила то, на что могли бы уйти поколения. Город, который стоит сегодня, большей частью их работа.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:illidan-stormrage}Предатель{/link}ство.{/b} Когда работа была окончена, {link:house-of-nobles}Палата знати{/link} отказалась заплатить каменщикам то, что им причиталось. Каменщики выступили с протестом, и протест перерос в бунт. В этом хаосе была убита королева {link:tiffin-wrynn}Тиффин Ринн{/link}.
• {b}Изгнание.{/b} Каменщиков выгнали из {link:stormwind-city}Штормград{/link}а. Ван Клиф увел их на запад, где они стали {link:defias-brotherhood}Братством Справедливости{/link}. Умения, которые построили город, были обращены на возведение крепостей для воров.]=],
		},
		{
			title = "Наши дни",
			text = [=[Знак старой гильдии сохранился на кольцах Братства и в каменной кладке Мертвых копей. По всему {link:elwynn-forest}Элвинн{/link}скому лесу и Западному Краю каменщики теперь строят для Братства. Стены {link:stormwind-city}Штормград{/link}а все еще стоят как лучшее доказательство того, на что была способна гильдия.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, что сталось с каменщиками, которые не пошли в изгнание за своим главой, и трудится ли в {link:stormwind-city}Штормград{/link}е сегодня какая-нибудь гильдия каменщиков.]=],
		},
	},
})

Translate("ruRU", "house-of-nobles", {
	title = "Палата знати",
	sections = {
		{
			title = "Обзор",
			text = [=[Палата знати — собрание великих лордов {link:stormwind-city}Штормград{/link}а. Ее члены владеют землями, богатством и старинными титулами и издавна приложили руку к казне королевства и его законам. Именно их отказ платить каменщикам направил королевство по дороге к его нынешним бедам.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не сообщает, когда Палата знати собралась впервые. Она столь же стара, как знатные семьи королевства, и пережила огонь и изгнание. Когда {link:stormwind-city}Штормград{/link} отстраивали после {link:second-war}Второй войны{/link}, Палата стояла рядом с молодым королем {link:varian-wrynn}Варианом Ринном{/link}, и ее голос имел большой вес при новом дворе.]=],
		},
		{
			title = "История",
			text = [=[• {b}Плата каменщикам.{/b} {link:stonemasons-guild}Гильдия каменщиков{/link} отстроила столицу, и вел ее {link:edwin-vancleef}Эдвин ван Клиф{/link}. Когда работа была окончена, Палата знати отказалась заплатить каменщикам то, что им причиталось. Протест каменщиков обернулся бунтом, и в этих беспорядках погибла королева {link:tiffin-wrynn}Тиффин Ринн{/link}. Каменщиков изгнали, и они стали {link:defias-brotherhood}Братством Справедливости{/link}.
• {b}Вина.{/b} Многие в {link:stormwind-city}Штормград{/link}е до сих пор винят знать в смерти королевы и в появлении Братства. Знать, со своей стороны, винит каменщиков.]=],
		},
		{
			title = "Наши дни",
			text = [=[Король исчез, и знать имеет большое влияние на регентство, которое несет верховный лорд {link:bolvar-fordragon}Болвар Фордрагон{/link}. Леди {link:katrana-prestor}Катрана Престор{/link} стала среди знати любимицей, и ее советы слышны в каждом споре. Простолюдины ворчат, что лорды спорят о налогах, пока горит {link:westfall}Западный Край{/link}. Регенту приходится угождать знати, и это не облегчает его задачу.]=],
		},
	},
})

Translate("ruRU", "si-7", {
	title = "SI:7",
	sections = {
		{
			title = "Обзор",
			text = [=[SI:7 — тайная служба {link:kingdom-of-stormwind}королевства Штормград{/link}. Ее агенты — шпионы, разведчики и убийцы, которые служат короне в молчании. Они следят за врагами королевства и за его стенами, и внутри них. Немногие в {link:stormwind-city}Штормград{/link}е знают о них хоть что-то, и именно это их устраивает.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не сообщает, когда была основана SI:7 и кто первым дал ей это имя. Она служит королям {link:stormwind-city}Штормград{/link}а со времен, что были еще до {link:third-war}Третьей войны{/link}, и ее агенты всегда трудились вдали от света двора.]=],
		},
		{
			title = "История",
			text = [=[• {b}В тенях.{/b} SI:7 много лет охотится на скрытых врагов королевства. Она следила за соперничающими королевствами, за изменниками дома и за опасными культами. Ее члены набираются главным образом из разбойников {link:stormwind-city}Штормград{/link}а, которых обучают в ее штабе.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:master-mathias-shaw}Мастер Матиас Шоу{/link} руководит SI:7 из ее штаба в Старом городе, в {link:stormwind-city}Штормграде{/link}. Его агенты идут по следам {link:defias-brotherhood}Братства Справедливости{/link} по всему {link:westfall}Западному Краю{/link}, следят за союзниками Братства и доносят о странных делах среди {link:forsaken}Отрекшихся{/link}. Некоторые служат в {link:theramore-isle}Терамор{/link}е и охраняют власть его правительницы, {link:jaina-proudmoore}Джайны Праудмур{/link}. Другие примкнули к разбойникам Черного Ворона в войне против {link:syndicate}Синдиката{/link}. Теперь, когда король исчез, а войско в чужих краях, тихая работа главы службы важна как никогда.]=],
		},
	},
})

Translate("ruRU", "explorers-league", {
	title = "Лига исследователей",
	sections = {
		{
			title = "Обзор",
			text = [=[Лига исследователей — общество ученых и искателей приключений из числа дворфов, которое обосновалось в {link:ironforge}Стальгорне{/link}. Ее члены выкапывают реликвии, наносят на карты забытые руины и изучают тайны древнего мира. Более всего они ищут истинное происхождение {link:dwarves}народа дворфов{/link} и верят, что ответ п{link:ogres}огр{/link}ебен в камне.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:dwarves}Дворфы{/link} всегда копали глубоко, но Лига превратила раскопки в науку. Из своего Зала Исследователей в {link:ironforge}Стальгорн{/link}е она рассылает экспедиции по всему миру и собирает то, что они находят. Ее члены ценят знание так же высоко, как золото. Они известны своей отвагой и не меньше известны пренебрежением к опасности.]=],
		},
		{
			title = "История",
			text = [=[• {b}Великие раскопки.{/b} Лига издавна полагает, что {link:dwarves}дворф{/link}ов создали из камня титаны, творцы мира. Ее экспедиции ищут доказательства этого в древних руинах по всему Каз Модану и за его пределами.
• {b}Знаменитые имена.{/b} Среди ее членов — {link:brann-bronzebeard}Бранн Бронзобород{/link}, самый прославленный исследователь своего времени; его брат — король {link:magni-bronzebeard}Магни Бронзобород{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:high-explorer-magellas}Верховный исследователь Магеллас{/link} руководит Лигой из Зала Исследователей. Ее раскопки разбросаны по миру: {link:ironband-s-excavation-site}Раскопки Сталекрута{/link} в {link:loch-modan}Лок Модане{/link}, {link:bael-modan}Бейл Модан{/link} в {link:the-barrens}Степях{/link} и руины {link:uldaman}Ульдаман{/link}а в {link:badlands}Бесплодных землях{/link}. В {link:wetlands}Болотине{/link} {link:whelgar-s-excavation-site}Раскопки Вельгара{/link} обнаружили нечто такое, к чему землекопы не были готовы. Нападения {link:troggs}трогг{/link}ов и притязания соперников досаждают многим из этих раскопок, но Лига не сдается легко.]=],
		},
	},
})

Translate("ruRU", "cenarion-circle", {
	title = "Круг Кенария",
	sections = {
		{
			title = "Обзор",
			text = [=[Круг Кенария — орден друидов, хранителей природы. Его члены черпают силу в земле и в {link:emerald-dream}Изумрудном Сне{/link} и поклялись защищать мир живого. {link:krueg-skullsplitter}Круг{/link} назван в честь полубога Кенария. Долгое время он был орденом {link:night-elves}ночных эльфов{/link}, а ныне числит среди своих членов и {link:tauren}тауренов{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Первым друидом ночных эльфов был {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, которого учил сам {link:cenarius}Кенарий{/link}. Во время {link:war-of-the-ancients}Войны древних{/link} Малфурион и его последователи обратили свое новое искусство против {link:burning-legion}Пылающего Легиона{/link}. После {link:great-sundering}Великого Раскола{/link} друиды стали стражами земель ночных эльфов. Тысячи лет они спали в Изумрудном Сне и пробуждались только в час нужды.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:third-war}Третья война{/link}.{/b} Друидов разбудили, чтобы они вновь встретили Легион. Они сражались в {link:battle-of-mount-hyjal}битве у горы Хиджал{/link}, где Древо Жизни {link:nordrassil}Нордрассил{/link} было принесено в жертву, чтобы был уничтожен {link:archimonde}Архимонд{/link}.
• {b}Открытый {link:krueg-skullsplitter}Круг{/link}.{/b} За прошедшие годы Круг принял друидов-{link:tauren}таурен{/link}ов, и первым среди них был {link:hamuul-runetotem}Хамуул Рунический Тотем{/link}. Он стоит в стороне и от {link:alliance}Альянса{/link}, и от {link:horde}Орды{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Сердце {link:krueg-skullsplitter}Круг{/link}а — {link:moonglade}Лунная поляна{/link}, священная долина, где несет стражу {link:keeper-remulos}Хранитель Ремулос{/link}, сын полубога Кенария. Его друиды заботятся о диких местах {link:kalimdor}Калимдора{/link} и пытаются исцелить порчу {link:felwood}Оскверненного леса{/link}. {link:malfurion-stormrage}Малфурион{/link} удалился в {link:emerald-dream}Изумрудный Сон{/link}. В его отсутствие верховный друид {link:fandral-staghelm}Фэндрал Олений Шлем{/link} ведет друидов {link:darnassus}Дарнасса{/link}, где выращено новое Древо Жизни, {link:teldrassil}Тельдрассил{/link}.]=],
		},
	},
})

Translate("ruRU", "earthen-ring", {
	title = "Служители Земли",
	sections = {
		{
			title = "Обзор",
			text = [=[Служители Земли — совет шаманов, преданных равновесию {link:elements}стихий{/link}. Его члены слушают духов земли, огня, воды и воздуха и стремятся удержать эти силы в согласии. Служители стоят выше раздоров между народами. Их взор обращен на сам мир.]=],
		},
		{
			title = "Истоки",
			text = [=[Служителей Земли давным-давно основали {link:tauren}таурены{/link}, чтобы направлять свой народ мудростью и хранить мир между духами стихий. Их старейшины собираются на совет уже много поколений. Шаманы совета не повелевают стихиями. Они просят, и торгуются, и помнят, что духи не слуги.]=],
		},
		{
			title = "История",
			text = [=[• {b}Новые шаманы.{/b} Когда {link:thrall}Тралл{/link} вернул {link:orcs}орк{/link}ов на пути шаманов, дороги {link:tauren}таурен{/link}ов и орков сошлись. После {link:third-war}Третьей войны{/link} Служители Земли начали принимать в свои круги шаманов из орков и троллей.
• {b}Отрекшиеся.{/b} Когда {link:forsaken}Отрекшиеся{/link} попросили принять их в {link:horde}Орду{/link}, они уверяли, что ищут лекарство от своей участи нежити в целительных силах земли. Тралл и {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link} отнеслись к ним с опаской. Именно {link:shadow-council}Совет{/link} старейшин Служителей убедил Орду помочь им.]=],
		},
		{
			title = "Наши дни",
			text = [=[Шаманы Служителей Земли присматривают за стихиями {link:kalimdor}Калимдора{/link} и иных земель. То, что они слышат, их тревожит. В недрах Черной горы бушует огонь, и стихии во многих землях становятся беспокойными. Служителей ведет {link:muln-earthfury}Мулн Гнев Земли{/link}, {link:tauren}таурен{/link} великой мудрости, хотя он редко показывается.]=],
		},
	},
})

Translate("ruRU", "twilight-s-hammer", {
	title = "Сумеречный Молот",
	sections = {
		{
			title = "Обзор",
			text = [=[Сумеречный Молот — культ погибели. Некогда это был орочий клан Орды. Теперь это братство безумцев всех рас, которые поклоняются древним силам, п{link:ogres}огр{/link}ебенным под миром, и жаждут конца всего сущего. Там, где собирается культ, во тьме совершаются странные обряды.]=],
		},
		{
			title = "Истоки",
			text = [=[Сумеречный Молот был кланом Орды, который вел Чо'галл, двухголовый {link:ogres}огр{/link}-маг, один из ближайших слуг чернокнижника {link:gul-dan}Гул'дана{/link}. Даже среди {link:orcs}орк{/link}ов членов клана боялись как фанатиков. Они верили, что мир обречен и что их задача — ускорить его конец.]=],
		},
		{
			title = "История",
			text = [=[• {b}Вторая война.{/b} В разгар {link:second-war}Второй войны{/link} {link:gul-dan}Гул'дан{/link} предал Орду ради поисков Гробницы {link:sargeras}Саргерас{/link}а. Чо'галл и его клан последовали за ним. Вождь {link:orgrim-doomhammer}Оргрим Молот Рока{/link} обратил свои войска против изменников и разбил клан, а {link:alliance}Альянс{/link} воспользовался этим хаосом. Ни одна летопись этой эпохи не говорит, какая судьба постигла {link:ogres}огр{/link}а-мага.
• {b}Возрожденный культ.{/b} Клан не умер. Он стал культом, преданным Древним богам — темным силам, заточенным глубоко в недрах {link:azeroth}Азерота{/link}. Он начал втягивать в себя членов многих рас, которые разделяли его жажду разрушения.]=],
		},
		{
			title = "Наши дни",
			text = [=[Культ действует в потаенных местах. Его членов находили в затопленных руинах Непроглядной Пучины в {link:ashenvale}Ясеневом лесу{/link}, где они совершают темные обряды среди {link:naga}наг{/link}. Говорят, что его лагеря лежат в пустыне {link:silithus}Силитус{/link}, далеко на юге. Никто не знает, сколько их служит Молоту и как близко его члены стоят к тронам мира.]=],
		},
	},
})

Translate("ruRU", "burning-blade", {
	title = "Пылающий Клинок",
	sections = {
		{
			title = "Обзор",
			text = [=[Пылающий Клинок некогда был орочьим кланом грозных мечников. Теперь это главным образом культ поклонников демонов, который прячется среди {link:orcs}орк{/link}ов новой {link:horde}Орды{/link}. Его члены служат {link:burning-legion}Пылающему Легиону{/link} и стараются утащить свой народ обратно в порчу, от которой его освободил {link:thrall}Тралл{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[На Дреноре Пылающий Клинок был кланом {link:orcs}орк{/link}ов, прославленным своими мастерами клинка. Когда орки попали под власть демонов, Пылающий Клинок пал ниже большинства. В {link:first-war}Первую войну{/link} и во {link:second-war}Вторую войну{/link} его воины были беспорядочным братством, обезумевшим от битв и не верным никому. Их спускали на врага только в час великой нужды.]=],
		},
		{
			title = "История",
			text = [=[• {b}Два пути.{/b} После Второй войны некоторые мастера клинка этого клана примкнули к новой Орде и поклялись освободиться от власти демонов. Другие остались верны демонам. Под началом {link:shadow-council}Совет{/link}а Теней, последних орочьих чернокнижников, они стали тайным культом.
• {b}Культ ширится.{/b} Культ принял членов других рас, даже людей и Отрекшихся, которые разделяют его преданность Легиону.]=],
		},
		{
			title = "Наши дни",
			text = [=[Пылающий Клинок гноится в {link:durotar}Дуротаре{/link} и в {link:the-barrens}Степях{/link}. Его сектанты прячутся в пещерах Дуротара, у Скалы Черепа и в Пещере Пыльного Ветра, и строят козни под самим {link:orgrimmar}Оргриммар{/link}ом. В {link:desolace}Пустошах{/link} они удерживают {link:thunder-axe-fortress}Крепость Громового Топора{/link}, где их хозяева-демоны ходят открыто. Воины Орды охотятся на них без отдыха, но культ, похоже, всегда находит новых сторонников.]=],
		},
	},
})

Translate("ruRU", "dark-iron-dwarves", {
	title = "Дворфы Черного Железа",
	aliases = { "клан Черного Железа" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дворфы Черного Железа — самый грозный из трех кланов {link:dwarves}дворф{/link}ов. Они мастера огня и темной магии. Два века назад они пошли войной на своих сородичей и, потерпев поражение, выпустили на волю повелителя пламени, который поработил их. Теперь они живут в недрах Черной горы и связаны службой повелителю огня {link:ragnar-thunderbrew}Рагнар{/link}осу.]=],
		},
		{
			title = "Истоки",
			text = [=[Давным-давно {link:dwarves}дворфы{/link} Каз Модана были одним народом, которым из {link:ironforge}Стальгорна{/link} правил верховный король Модимус Анвилмар. Когда он умер, за трон стали биться три клана: Бронзобороды, Неистовый Молот и Черное Железо, которым правил тан-чародей {link:ruins-of-thaurissan}Тауриссан{/link}. Клан Бронзобородов победил и изгнал остальных. Дворфы Черного Железа ушли на юг и построили среди гор город, который тоже звался Тауриссан.]=],
		},
		{
			title = "История",
			text = [=[• {b}Война Трех Молотов.{/b} Примерно за двести тридцать лет до Темного портала {link:dwarves}дворф{/link}ы Черного Железа напали и на {link:ironforge}Стальгорн{/link}, и на {link:grim-batol}Грим Батол{/link}, твердыню клана Неистового Молота. Они были разбиты у ворот Стальгорна.
• {b}Приход повелителя огня.{/b} В отчаянии {link:ruins-of-thaurissan}Тауриссан{/link} стал искать великую силу себе в помощь. Он призвал повелителя огненных элементалей: это был {link:ragnar-thunderbrew}Рагнар{/link}ос. Приход повелителя огня разорвал землю и создал {link:searing-gorge}Тлеющее ущелье{/link} и {link:burning-steppes}Пылающие степи{/link}. Там, где стоял город, поднялась {link:blackrock-mountain}Черная гора{/link}, а дворфы Черного Железа стали рабами своего нового господина.]=],
		},
		{
			title = "Наши дни",
			text = [=[Император Дагран {link:ruins-of-thaurissan}Тауриссан{/link} правит {link:dwarves}дворф{/link}ами Черного Железа из Тенегорна, глубоко в недрах Черной горы. {link:ragnar-thunderbrew}Рагнар{/link}ос правит ими всеми из Огненных Недр внизу. Отряды Черного Железа совершают набеги на {link:searing-gorge}Тлеющее ущелье{/link}, ведут раскопки в {link:badlands}Бесплодных землях{/link} и угрожают {link:wetlands}Болотине{/link}. Король {link:magni-bronzebeard}Магни Бронзобород{/link} утверждает, что его дочь Мойра была похищена императором, и хочет ее вернуть.]=],
		},
	},
})

Translate("ruRU", "steamwheedle-cartel", {
	title = "Картель Хитрая Шестеренка",
	aliases = { "Хитрая Шестеренка" },
	sections = {
		{
			title = "Обзор",
			text = [=[Картель Хитрая Шестеренка — крупнейшая из торговых компаний гоблинов. Он владеет портами и городами по обе стороны моря и держит их открытыми для любого покупателя с золотом. У картеля одна верность — прибыль. Нейтралитет сделал его богатым, и он охраняет этот нейтралитет наемными кулаками.]=],
		},
		{
			title = "Истоки",
			text = [=[Во время {link:second-war}Второй войны{/link} гоблины служили старой {link:horde}Орде{/link}. Торговый принц картеля продавал {link:orcs}орк{/link}ам машины, карты, алхимические зелья и дирижабли и строил корабли для флота, который собирал Молот Рока. Когда Орда была разбита, гоблины усвоили урок. Продавать обеим сторонам оказалось выгоднее, чем принимать одну из них.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:booty-bay}Пиратская бухта{/link}.{/b} Перед {link:first-war}Первой войной{/link} гоблины картеля выгнали троллей из маленького порта на южной оконечности Тернистой долины. Они сделали его своей гаванью — Пиратской бухтой.
• {b}За морем.{/b} В последующие годы картель построил или прибрал к рукам города по всему {link:kalimdor}Калимдору{/link}: {link:ratchet}Кабестан{/link} на побережье {link:the-barrens}Степей{/link}, {link:gadgetzan}Прибамбасск{/link} в пустыне {link:tanaris}Танарис{/link} и {link:everlook}Круговзор{/link} на ледяном севере {link:winterspring}Зимних Ключей{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Города картеля — убежища, где {link:orcs}орк{/link} и человек могут торговать, не обнажая стали. Их вышибалы поддерживают порядок тяжелой рукой. {link:baron-revilgaz}Барон Ревилгаз{/link} правит Пиратской бухтой, {link:gazlowe}Газлоу{/link} присматривает за {link:ratchet}Кабестан{/link}ом, а мэр {link:marin-noggenfogger}Гогельмогель{/link} управляет {link:gadgetzan}Прибамбасск{/link}ом. Каждый город борется с пиратами, соперничающими компаниями и дикими землями вокруг. Многие беды картеля исходят от {link:venture-company}Торговой Компании{/link}, гоблинского картеля, у которого нет и следа его манер.]=],
		},
	},
})

Translate("ruRU", "venture-company", {
	title = "Торговая Компания",
	sections = {
		{
			title = "Обзор",
			text = [=[Торговая Компания — гоблинский картель, который обдирает мир ради его богатств. Если что-то можно добыть из недр, срубить или выкачать из земли, Торговая Компания это заберет, и ей нет дела до того, кто жил там раньше. Ее крошшеры и буры оставляют за собой отравленные озера и голые холмы.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не сообщает об основании Торговой Компании. Это один из гоблинских картелей Нижней Шахты, и уже много лет ее возглавляет ее президент, магнат Раздунк. В отличие от {link:steamwheedle-cartel}картеля Хитрая Шестеренка{/link}, она не держит нейтральных городов и даже не притворяется, что знает честь.]=],
		},
		{
			title = "История",
			text = [=[• {b}В Калимдоре.{/b} Компания пришла в {link:kalimdor}Калимдор{/link} после {link:third-war}Третьей войны{/link} и принялась его грабить. Она качала нефть на Нефтяном болоте в {link:the-barrens}Степях{/link}. Она рубила леса {link:stonetalon-mountains}Когтистых гор{/link} и вгрызалась в утесы {link:mulgore}Мулгора{/link}, после того как {link:tauren}таурены{/link} отказали ей в этом праве.
• {b}В Восточных королевствах.{/b} В Тернистой долине компания вырубала джунгли ради древесины и копала в поисках редких кристаллов. Она также продавала темные тайны {link:defias-brotherhood}Братству Справедливости{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Торговая Компания трудится по всему миру. Она отравляет {link:water-wells-of-mulgore}колодцы Мулгора{/link} и терзает леса Когтистых гор {link:ogres}огр{/link}омными машинами. {link:tauren}Таурены{/link}, ночные эльфы и гоблины Хитрой Шестеренки — все считают ее врагом. Ее надсмотрщикам это безразлично, пока руда продолжает идти.]=],
		},
	},
})

Translate("ruRU", "syndicate", {
	title = "Синдикат",
	sections = {
		{
			title = "Обзор",
			text = [=[Синдикат — преступный союз падшей знати {link:alterac-mountains}Альтерак{/link}а. Он состоит из воров, убийц и разбойников, которые служат лордам без королевства. Его члены разоряют Альтеракские горы, {link:hillsbrad-foothills}Предгорья Хилсбрада{/link} и {link:arathi-highlands}Нагорье Арати{/link} и мечтают о короне, которую у них отняли.]=],
		},
		{
			title = "Истоки",
			text = [=[Во {link:second-war}Вторую войну{/link} {link:aiden-perenolde}лорд Айден Перенольд{/link}, король {link:alterac-mountains}Альтерак{/link}а, предал {link:alliance}Альянс Лордерона{/link} {link:horde}Орде{/link}. Когда война окончилась, Альтерак лишили короны и земель. Знать Альтерака так и не простила другие королевства. Ее возглавил наследник короля-изменника, лорд {link:lord-aliden-perenolde}Алиден Перенольд{/link}; знатные изгнанники собрали воров и наемников и сделали из них Синдикат.]=],
		},
		{
			title = "История",
			text = [=[• {b}До Третьей войны.{/b} Бандиты Синдиката уже промышляли в лесах {link:alterac-mountains}Альтерак{/link}а до того, как чума поразила {link:lordaeron}Лордерон{/link}.
• {b}После падения.{/b} Когда Лордерон пал, Синдикат расползся по руинам, которые тот оставил. Он захватил {link:durnholde-keep}Крепость Дарнхольд{/link} в {link:hillsbrad-foothills}Предгорьях Хилсбрада{/link} и большую часть {link:stromgarde-keep}Стромгард{/link}а в {link:arathi-highlands}Нагорье Арати{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:lord-aliden-perenolde}Алиден Перенольд{/link} руководит Синдикатом из Овчарни Дандреда в {link:alterac-mountains}Альтеракских горах{/link}, а городок {link:strahnbrad}Странбрад{/link} служит Синдикату крепостью. {link:lord-falconcrest}Лорд Фальконкрест{/link} командует его силами в руинах {link:stromgarde-keep}Стромгард{/link}а. Синдикат крадет лошадей и грузы из Южнобережья и устраивает засады на солдат Стромгарда. Разбойники Черного Ворона ведут против него долгую войну, а {link:forsaken}Отрекшиеся{/link} назначили цену за голову каждого его члена.]=],
		},
	},
})

Translate("ruRU", "royal-apothecary-society", {
	title = "Королевское общество аптекарей",
	sections = {
		{
			title = "Обзор",
			text = [=[Королевское общество аптекарей — орден алхимиков, который служит Королеве-банши {link:forsaken}Отрекшихся{/link}; ее имя — {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link}. В подземельях под {link:undercity}Подгород{/link}ом его аптекари варят яды и чуму. Их объявленная цель — лекарство от участи нежити. Их истинная цель темнее.]=],
		},
		{
			title = "Истоки",
			text = [=[Общество основала {link:sylvanas-windrunner}Сильвана{/link}, после того как {link:forsaken}Отрекшиеся{/link} завоевали свободу от {link:scourge}Плети{/link}. Его аптекари взялись сделать то, на что не решался ни один живой алхимик: взять чуму, которая создала Отрекшихся, и превратить ее в собственное оружие. Аптекари устроили свои лаборатории в {link:the-apothecarium}Аптекариум{/link}е, под Королевским кварталом в {link:undercity}Подгород{/link}е.]=],
		},
		{
			title = "История",
			text = [=[• {b}Лекарство и чума.{/b} Когда {link:forsaken}Отрекшиеся{/link} вступили в {link:horde}Орду{/link}, другие ее народы верили, что аптекари ищут лекарство от своей участи. На деле первым трудом общества была новая чума, предназначенная уничтожить {link:scourge}Плеть{/link}.
• {b}Иные искусства.{/b} Общество также поднимало мертвых лошадей, чтобы они служили Отрекшимся скакунами, и рассылает своих членов повсюду собирать новые ингредиенты.]=],
		},
		{
			title = "Наши дни",
			text = [=[В {link:the-apothecarium}Аптекариум{/link}е главный аптекарь {link:master-apothecary-faranell}Фаранелл{/link} надзирает за работой над новой чумой, а агенты общества испытывают ее на полях {link:hillsbrad-foothills}Предгорий Хилсбрада{/link} и в иных местах. Его аптекари служат на каждой заставе Отрекшихся. Их союзники в Орде наблюдают за ними с растущей тревогой.]=],
		},
	},
})

Translate("ruRU", "darkspear-trolls", {
	title = "Племя Черного Копья",
	aliases = { "тролли Черного Копья", "Черное Копье" },
	sections = {
		{
			title = "Обзор",
			text = [=[Черное Копье — племя лесных {link:trolls}троллей{/link}, которое стоит на стороне {link:horde}Орды{/link}. Они были изгоями и скитальцами, пока {link:thrall}Тралл{/link} не спас их от гибели. Теперь они самые верные союзники {link:orcs}орк{/link}ов. Они охотники, знахари и свирепые воины и обязаны вождю Орды своим спасением.]=],
		},
		{
			title = "Истоки",
			text = [=[Племя Черного Копья некогда было одним из племен Гурубаши, лесных троллей Тернистой долины. Когда империя Гурубаши распалась, ее племена обратились друг против друга, и племя Черного Копья было изгнано. Оно обрело новый дом на островах в южных морях.]=],
		},
		{
			title = "История",
			text = [=[• {b}Спасение.{/b} Когда буря выбросила флот {link:orcs}орк{/link}ов на их остров, племя Черного Копья было в большой опасности. На него нападали люди {link:kul-tiras}Кул Тираса{/link} и морские {link:murlocs}мурлок{/link}и. {link:thrall}Тралл{/link} сражался рядом с троллями, а их предводитель, Сен'джин, был схвачен. Сен'джин умер пленником мурлоков, но успел предвидеть, что Тралл приведет его народ к новому дому.
• {b}Калимдор.{/b} Племя Черного Копья отплыло с Ордой в {link:kalimdor}Калимдор{/link} и поселилось на Островах Эха у побережья {link:durotar}Дуротара{/link}.
• {b}{link:zalazane}Залазан{/link}.{/b} Знахарь Залазан обратился против своего племени. Темным вуду он поработил многих троллей Островов Эха, а остальных выгнал из их домов.]=],
		},
		{
			title = "Наши дни",
			text = [=[Свободные тролли Черного Копья поселились на побережье {link:durotar}Дуротар{/link}а, в Деревне Сен'джин, которую назвали в честь погибшего предводителя. Их ведет его сын, {link:vol-jin}Вол'джин{/link}, который стоит рядом с вождем Орды в {link:orgrimmar}Оргриммар{/link}е. {link:zalazane}Залазан{/link} по-прежнему правит Островами Эха, и племя Черного Копья намерено их вернуть.]=],
		},
	},
})

Translate("ruRU", "kingdom-of-ironforge", {
	title = "Королевство Стальгорн",
	sections = {
		{
			title = "Обзор",
			text = [=[Королевство Стальгорн — держава {link:dwarves}дворфов{/link} клана Бронзобородов. Его столица вырублена в сердце горы в {link:dun-morogh}Дун Мороге{/link}, и его горны горят тысячи лет. Это королевство рудокопов, кузнецов, инженеров и ученых. Оно же — один из двух столпов {link:alliance}Альянса{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:dwarves}Дворфы{/link} говорят, что в незапамятные времена были созданы из камня. Их древнейший город — {link:ironforge}Стальгорн{/link}, и долгое время всеми дворфами правили оттуда. Когда умер верховный король Модимус Анвилмар, кланы Бронзобородов, Неистового Молота и Черного Железа стали биться за трон. Клан Бронзобородов удержал Стальгорн и изгнал два других клана. В Войне Трех Молотов он разбил {link:dark-iron-dwarves}дворфов Черного Железа{/link} у ворот города.]=],
		},
		{
			title = "История",
			text = [=[• {b}Друзья людей.{/b} Исследователи из {link:arathor}Аратора{/link} давным-давно добрались до Каз Модана. {link:dwarves}Дворфы{/link} и люди подружились и обменивались знаниями о кузнечном деле, инженерии и магии.
• {b}{link:second-war}Вторая война{/link}.{/b} Когда {link:horde}Орда{/link} захватила Каз Модан, сам {link:ironforge}Стальгорн{/link} выстоял. Дворфы вступили в {link:alliance}Альянс Лордерона{/link} и не забыли, кто стоял с ними рядом.
• {b}{link:third-war}Третья война{/link}.{/b} У короля {link:magni-bronzebeard}Магни Бронзоборода{/link} был брат, {link:muradin-bronzebeard}Мурадин Бронзобород{/link}. Он отправился в Нордскол с принцем {link:arthas-menethil}Артасом Менетилом{/link} и не вернулся. Дворфы оплакивают его как погибшего.
• {b}Падение Гномрегана.{/b} Когда {link:gnomeregan}Гномреган{/link} был потерян, Магни дал уцелевшим {link:gnomes}гномам{/link} дом в своем городе.]=],
		},
		{
			title = "Наши дни",
			text = [=[Король {link:magni-bronzebeard}Магни{/link} правит {link:ironforge}Стальгорн{/link}ом. Его младший брат {link:brann-bronzebeard}Бранн Бронзобород{/link} странствует по миру ради {link:explorers-league}Лиги исследователей{/link}. {link:gnomes}Гномы{/link}, которых возглавляет {link:gelbin-mekkatorque}Гелбин Меггакрут{/link}, живут в Городе Механиков, в сердце города. Солдаты-{link:dwarves}дворф{/link}ы охраняют {link:loch-modan}Лок Модан{/link} и перевалы юга. {link:dark-iron-dwarves}Дворфы Черного Железа{/link} угрожают из Черной горы, а Магни скорбит о своей дочери Мойре, которую, по его словам, похитил их император.]=],
		},
	},
})
